#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "adi.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	u[i][j] =  (DATA_TYPE)(i + n-j) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */

static 
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(u,N,N,n,n)) 

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("u");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, u[i][j]);
    }
  POLYBENCH_DUMP_END("u");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;

  /* The formal parameters tsteps and n are kept for API compatibility,
     but the PolyBench macros _PB_TSTEPS and _PB_N are used to drive
     the loop bounds, as in the original code. */
  (void)tsteps;
  (void)n;

#pragma scop
  /* Precompute scalar constants once, outside the time-stepping loops.
     This improves instruction-level efficiency and keeps the hot loops
     free from redundant arithmetic. */
  const DATA_TYPE zero = SCALAR_VAL(0.0);
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);

  const DATA_TYPE DX = one / (DATA_TYPE)_PB_N;
  const DATA_TYPE DY = one / (DATA_TYPE)_PB_N;
  const DATA_TYPE DT = one / (DATA_TYPE)_PB_TSTEPS;

  const DATA_TYPE B1 = SCALAR_VAL(2.0);
  const DATA_TYPE B2 = one;

  const DATA_TYPE mul1 = B1 * DT / (DX * DX);
  const DATA_TYPE mul2 = B2 * DT / (DY * DY);

  const DATA_TYPE a = -mul1 / two;
  const DATA_TYPE b = one + mul1;
  const DATA_TYPE c = a;
  const DATA_TYPE d = -mul2 / two;
  const DATA_TYPE e = one + mul2;
  const DATA_TYPE f = d;

  /* Coefficients reused in every inner-loop iteration. */
  const DATA_TYPE one_plus_2d = one + two * d;
  const DATA_TYPE one_plus_2a = one + two * a;

  /* Cached problem sizes to avoid recomputing loop bounds. */
  const int tsteps_eff = _PB_TSTEPS;
  const int n_eff      = _PB_N;
  const int n_minus_1  = n_eff - 1;
  const int n_minus_2  = n_eff - 2;

  for (t = 1; t <= tsteps_eff; ++t) {
    /*--------------------------------------------------------------*
     * Column sweep: for each fixed column index i, solve a 1D
     * tridiagonal system along the j dimension to update v(:,i).
     * Each column (each i) is independent in this phase.
     *--------------------------------------------------------------*/
    for (i = 1; i < n_minus_1; ++i) {
      /* Cache the base addresses of p and q rows for this i.
         This reduces address arithmetic in the inner loops and
         improves cache locality for p and q. */
      DATA_TYPE *p_i = p[i];
      DATA_TYPE *q_i = q[i];

      v[0][i] = one;
      p_i[0]  = zero;
      q_i[0]  = one; /* equal to v[0][i] */

      /* Forward substitution along the column (over j). */
      for (j = 1; j < n_minus_1; ++j) {
        const DATA_TYPE p_prev = p_i[j-1];
        /* Denominator shared by p and q updates; compute once. */
        const DATA_TYPE den    = a * p_prev + b;

        /* Load the three neighboring u values participating in
           the stencil for this (j,i) position. */
        const DATA_TYPE u_j_im1 = u[j][i-1];
        const DATA_TYPE u_j_i   = u[j][i];
        const DATA_TYPE u_j_ip1 = u[j][i+1];

        p_i[j] = -c / den;

        q_i[j] = (-d * u_j_im1 +
                  one_plus_2d * u_j_i -
                  f * u_j_ip1 -
                  a * q_i[j-1]) / den;
      }

      v[n_minus_1][i] = one;

      /* Back substitution along the column (over j, decreasing). */
      for (j = n_minus_2; j >= 1; --j) {
        v[j][i] = p_i[j] * v[j+1][i] + q_i[j];
      }
    }

    /*--------------------------------------------------------------*
     * Row sweep: for each fixed row index i, solve a 1D
     * tridiagonal system along the j dimension to update u(i,:)
     * using the intermediate values v. Each row (each i) is
     * independent in this phase.
     *--------------------------------------------------------------*/
    for (i = 1; i < n_minus_1; ++i) {
      DATA_TYPE *p_i = p[i];
      DATA_TYPE *q_i = q[i];
      DATA_TYPE *u_i = u[i];

      u_i[0] = one;
      p_i[0] = zero;
      q_i[0] = one; /* equal to u[i][0] */

      /* Forward substitution along the row (over j). */
      for (j = 1; j < n_minus_1; ++j) {
        const DATA_TYPE p_prev = p_i[j-1];
        /* Denominator shared by p and q updates; compute once. */
        const DATA_TYPE den    = d * p_prev + e;

        const DATA_TYPE v_im1_j = v[i-1][j];
        const DATA_TYPE v_i_j   = v[i][j];
        const DATA_TYPE v_ip1_j = v[i+1][j];

        p_i[j] = -f / den;

        q_i[j] = (-a * v_im1_j +
                  one_plus_2a * v_i_j -
                  c * v_ip1_j -
                  d * q_i[j-1]) / den;
      }

      u_i[n_minus_1] = one;

      /* Back substitution along the row (over j, decreasing). */
      for (j = n_minus_2; j >= 1; --j) {
        u_i[j] = p_i[j] * u_i[j+1] + q_i[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_adi (tsteps, n, POLYBENCH_ARRAY(u), POLYBENCH_ARRAY(v), POLYBENCH_ARRAY(p), POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
