/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 *
 * Optimizations:
 *  - Introduce local restrict-qualified aliases for the 2D arrays to
 *    help the compiler assume non-aliasing.
 *  - Hoist loop-invariant scalar expressions and precompute frequently
 *    used combinations of constants.
 *  - In the tridiagonal solves, factor out the common denominator
 *    (a*p + b) or (d*p + e), compute its reciprocal once per iteration,
 *    and replace two divisions with one division plus multiplications.
 *    This is mathematically equivalent and significantly cheaper.
 *  - Use row pointers (p_row, q_row, u_row, v_* rows) to reduce
 *    2D indexing overhead inside inner loops and improve cache locality.
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;

  /* Local restrict-qualified aliases for better optimization.  The
     PolyBench harness allocates u, v, p, q as distinct arrays. */
  DATA_TYPE (* __restrict u_)[N] = u;
  DATA_TYPE (* __restrict v_)[N] = v;
  DATA_TYPE (* __restrict p_)[N] = p;
  DATA_TYPE (* __restrict q_)[N] = q;

  /* Scalar coefficients. */
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

  /* Pre-computed helpers to reduce work in the inner loops. */
  DATA_TYPE zero, one, two;
  DATA_TYPE one_plus_2d, one_plus_2a;

  /* Cache PolyBench loop bounds into plain integers. */
  const int n_pb   = _PB_N;
  const int t_pb   = _PB_TSTEPS;
  const int n_last = n_pb - 1;

#pragma scop

  zero = SCALAR_VAL(0.0);
  one  = SCALAR_VAL(1.0);
  two  = SCALAR_VAL(2.0);

  DX = one / (DATA_TYPE)n_pb;
  DY = one / (DATA_TYPE)n_pb;
  DT = one / (DATA_TYPE)t_pb;
  B1 = SCALAR_VAL(2.0);
  B2 = one;

  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 / two;
  b =  one + mul1;
  c =  a;
  d = -mul2 / two;
  e =  one + mul2;
  f =  d;

  one_plus_2d = one + two * d;
  one_plus_2a = one + two * a;

  for (t = 1; t <= t_pb; t++) {
    /* Column sweep: implicit solve along columns (j dimension) to
       update v_. Each i-column is independent. */
    for (i = 1; i < n_last; i++) {
      DATA_TYPE * __restrict p_row = p_[i];
      DATA_TYPE * __restrict q_row = q_[i];

      /* Boundary conditions at j = 0. */
      v_[0][i] = one;
      p_row[0] = zero;
      q_row[0] = one; /* equals v_[0][i] */

      /* Forward sweep in j: factorization / forward substitution. */
      for (j = 1; j < n_last; j++) {
        DATA_TYPE * __restrict u_row = u_[j];

        DATA_TYPE denom     = a * p_row[j-1] + b;
        DATA_TYPE inv_denom = one / denom;

        /* Both p_row[j] and q_row[j] share the same denominator, so
           compute its reciprocal once and use multiplication. */
        p_row[j] = -c * inv_denom;

        q_row[j] = (-d * u_row[i-1] +
                    one_plus_2d * u_row[i] -
                    f * u_row[i+1] -
                    a * q_row[j-1]) * inv_denom;
      }

      /* Boundary condition at j = n_pb-1. */
      v_[n_last][i] = one;

      /* Backward substitution in j. */
      for (j = n_last-1; j >= 1; j--) {
        v_[j][i] = p_row[j] * v_[j+1][i] + q_row[j];
      }
    }

    /* Row sweep: implicit solve along rows (j dimension) to update u_. */
    for (i = 1; i < n_last; i++) {
      DATA_TYPE * __restrict p_row = p_[i];
      DATA_TYPE * __restrict q_row = q_[i];
      DATA_TYPE * __restrict u_row = u_[i];

      /* Neighboring rows of v_ reused in the inner loop. */
      const DATA_TYPE * __restrict v_im1 = v_[i-1];
      const DATA_TYPE * __restrict v_i   = v_[i];
      const DATA_TYPE * __restrict v_ip1 = v_[i+1];

      /* Boundary conditions at j = 0. */
      u_row[0] = one;
      p_row[0] = zero;
      q_row[0] = u_row[0];

      /* Forward sweep in j. */
      for (j = 1; j < n_last; j++) {
        DATA_TYPE denom     = d * p_row[j-1] + e;
        DATA_TYPE inv_denom = one / denom;

        p_row[j] = -f * inv_denom;

        q_row[j] = (-a * v_im1[j] +
                    one_plus_2a * v_i[j] -
                    c * v_ip1[j] -
                    d * q_row[j-1]) * inv_denom;
      }

      /* Boundary condition at j = n_pb-1. */
      u_row[n_last] = one;

      /* Backward substitution in j. */
      for (j = n_last-1; j >= 1; j--) {
        u_row[j] = p_row[j] * u_row[j+1] + q_row[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);


