/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;
  /* Reused coefficients (set after a and d are known). */
  DATA_TYPE one_plus_two_d, one_plus_two_a;

  /* Scalar constants, expressed via SCALAR_VAL for portability
   * across different DATA_TYPE definitions. */
  const DATA_TYPE one  = SCALAR_VAL(1.0);
  const DATA_TYPE two  = SCALAR_VAL(2.0);
  const DATA_TYPE zero = SCALAR_VAL(0.0);

  /* Local restrict-qualified pointers to help the compiler
   * with alias analysis and vectorization. */
  DATA_TYPE (* restrict u_)[n] = u;
  DATA_TYPE (* restrict v_)[n] = v;
  DATA_TYPE (* restrict p_)[n] = p;
  DATA_TYPE (* restrict q_)[n] = q;

  (void)tsteps; /* parameters kept for interface compatibility */
  (void)n;

#pragma scop

  /* Precompute coefficients (identical algebra to original code). */
  DX = one / (DATA_TYPE)_PB_N;
  DY = one / (DATA_TYPE)_PB_N;
  DT = one / (DATA_TYPE)_PB_TSTEPS;
  B1 = two;
  B2 = one;
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 / two;
  b = one + mul1;
  c = a;
  d = -mul2 / two;
  e = one + mul2;
  f = d;

  /* Coefficients that appear repeatedly inside the sweeps. */
  one_plus_two_d = one + two * d;
  one_plus_two_a = one + two * a;

  /* Main time-stepping loop. */
  for (t = 1; t <= _PB_TSTEPS; t++) {

    /* ============================================================
     * Column sweep
     * ------------------------------------------------------------
     * We solve, for each column i, an independent tridiagonal
     * system along the j dimension. Compared to the original code,
     * the forward and backward passes are reorganized so that the
     * innermost loops iterate over the second index of u/v, which
     * is contiguous in memory. This improves cache locality and
     * makes the inner loops amenable to SIMD vectorization.
     * The numerical operations performed for each (i,j) are
     * unchanged.
     * ============================================================ */

    /* Top boundary / initialization for all columns. */
    for (i = 1; i < _PB_N - 1; i++) {
      v_[0][i] = one;
      p_[i][0] = zero;
      q_[i][0] = v_[0][i];
    }

    /* Forward sweep in j (increasing j). For a fixed j, all i
     * iterations are independent, so the inner loop can safely
     * be vectorized. */
    for (j = 1; j < _PB_N - 1; j++) {
      DATA_TYPE * restrict u_row = u_[j];

#pragma GCC ivdep
      for (i = 1; i < _PB_N - 1; i++) {
        const DATA_TYPE p_prev = p_[i][j - 1];
        const DATA_TYPE q_prev = q_[i][j - 1];
        const DATA_TYPE denom  = a * p_prev + b;

        /* Forward coefficients p(i,j). */
        p_[i][j] = -c / denom;

        /* Use row pointer for u to improve locality. */
        const DATA_TYPE u_left   = u_row[i - 1];
        const DATA_TYPE u_center = u_row[i];
        const DATA_TYPE u_right  = u_row[i + 1];

        const DATA_TYPE rhs =
          (-d * u_left + one_plus_two_d * u_center -
           f * u_right - a * q_prev);

        q_[i][j] = rhs / denom;
      }
    }

    /* Bottom boundary for all columns. */
    for (i = 1; i < _PB_N - 1; i++) {
      v_[_PB_N - 1][i] = one;
    }

    /* Backward substitution in j (decreasing j).
     * Again, iterations in i are independent. */
    for (j = _PB_N - 2; j >= 1; j--) {
#pragma GCC ivdep
      for (i = 1; i < _PB_N - 1; i++) {
        v_[j][i] = p_[i][j] * v_[j + 1][i] + q_[i][j];
      }
    }

    /* ============================================================
     * Row sweep
     * ------------------------------------------------------------
     * Same algebra and loop ordering as the original implementation,
     * but we use row pointers for better locality and clearer code.
     * Each row i is processed independently with a forward and
     * backward pass along j.
     * ============================================================ */
    for (i = 1; i < _PB_N - 1; i++) {
      DATA_TYPE * restrict u_row     = u_[i];
      DATA_TYPE * restrict p_row     = p_[i];
      DATA_TYPE * restrict q_row     = q_[i];
      DATA_TYPE * restrict v_im1_row = v_[i - 1];
      DATA_TYPE * restrict v_i_row   = v_[i];
      DATA_TYPE * restrict v_ip1_row = v_[i + 1];

      u_row[0] = one;
      p_row[0] = zero;
      q_row[0] = u_row[0];

      /* Forward sweep along the row (increasing j). */
      for (j = 1; j < _PB_N - 1; j++) {
        const DATA_TYPE p_prev = p_row[j - 1];
        const DATA_TYPE q_prev = q_row[j - 1];
        const DATA_TYPE denom2 = d * p_prev + e;

        p_row[j] = -f / denom2;

        const DATA_TYPE v_left   = v_im1_row[j];
        const DATA_TYPE v_center = v_i_row[j];
        const DATA_TYPE v_right  = v_ip1_row[j];

        const DATA_TYPE rhs2 =
          (-a * v_left + one_plus_two_a * v_center -
           c * v_right - d * q_prev);

        q_row[j] = rhs2 / denom2;
      }

      /* Right boundary for the row. */
      u_row[_PB_N - 1] = one;

      /* Backward substitution (decreasing j). */
      for (j = _PB_N - 2; j >= 1; j--) {
        u_row[j] = p_row[j] * u_row[j + 1] + q_row[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
