/* Based on a Fortran code fragment from Figure 5 of
 * "Automatic Data and Computation Decomposition on Distributed Memory Parallel Computers"
 * by Peizong Lee and Zvi Meir Kedem, TOPLAS, 2002
 */
static
void kernel_adi[[gnu::flatten, gnu::noinline]](int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t;

  /* Alias the 2D arrays with restrict-qualified pointers to improve
     the compiler's ability to optimize memory accesses. */
  DATA_TYPE (* __restrict u_)[n] = u;
  DATA_TYPE (* __restrict v_)[n] = v;
  DATA_TYPE (* __restrict p_)[n] = p;
  DATA_TYPE (* __restrict q_)[n] = q;

  /* Effective problem sizes as used by PolyBench loop macros. */
  const int nPB = _PB_N;
  const int tPB = _PB_TSTEPS;

  /* Precompute all scalar coefficients once per kernel call.
     These are constant across all time steps. */
  const DATA_TYPE one = SCALAR_VAL(1.0);
  const DATA_TYPE two = SCALAR_VAL(2.0);

  const DATA_TYPE DX = one / (DATA_TYPE)nPB;
  const DATA_TYPE DY = one / (DATA_TYPE)nPB;
  const DATA_TYPE DT = one / (DATA_TYPE)tPB;

  const DATA_TYPE B1 = SCALAR_VAL(2.0);
  const DATA_TYPE B2 = SCALAR_VAL(1.0);

  const DATA_TYPE mul1 = B1 * DT / (DX * DX);
  const DATA_TYPE mul2 = B2 * DT / (DY * DY);

  const DATA_TYPE a = -mul1 / two;
  const DATA_TYPE b = one + mul1;
  const DATA_TYPE c = a;
  const DATA_TYPE d = -mul2 / two;
  const DATA_TYPE e = one + mul2;
  const DATA_TYPE f = d;

  /* Coefficients of the central terms in the tridiagonal systems.
     These used to be recomputed in every inner iteration as
     (1 + 2*d) and (1 + 2*a). */
  const DATA_TYPE center_d = one + two * d;
  const DATA_TYPE center_a = one + two * a;

  /* Boundary and zero values used repeatedly. */
  const DATA_TYPE boundary_value = one;
  const DATA_TYPE zero           = SCALAR_VAL(0.0);

#pragma scop
  for (t = 1; t <= tPB; ++t)
  {
    /* --------------------------------------------------------------
       Column Sweep
       --------------------------------------------------------------
       Each iteration of the i-loop works on:
         - one column of v_   (v_[][i]),
         - one row of p_ and q_ (p_[i][], q_[i][]),
       and reads from u_ only. There are no dependencies between
       different values of i, so we parallelize the outer loop.
    */
#pragma omp parallel for schedule(static)
    for (int i = 1; i < nPB - 1; ++i)
    {
      DATA_TYPE * __restrict p_row = p_[i];
      DATA_TYPE * __restrict q_row = q_[i];

      /* Boundary conditions on this column (i is fixed). */
      v_[0][i] = boundary_value;
      p_row[0] = zero;
      q_row[0] = boundary_value; /* equal to v_[0][i] */

      /* Forward sweep along j (rows). This is a tridiagonal solver
         with a recurrence in j, so it remains sequential in j. */
      for (int j = 1; j < nPB - 1; ++j)
      {
        /* Common denominator for p and q in this step. */
        const DATA_TYPE denom     = a * p_row[j - 1] + b;
        const DATA_TYPE inv_denom = one / denom;

        /* p[i][j] update: reuse inv_denom to avoid a second division. */
        p_row[j] = -c * inv_denom;

        /* q[i][j] update: numerator depends on three neighboring
           points of u_ and the previous q. */
        const DATA_TYPE uj_im1 = u_[j][i - 1];
        const DATA_TYPE uj_i   = u_[j][i];
        const DATA_TYPE uj_ip1 = u_[j][i + 1];

        const DATA_TYPE rhs =
          (-d * uj_im1) + (center_d * uj_i) - (f * uj_ip1) - (a * q_row[j - 1]);

        q_row[j] = rhs * inv_denom;
      }

      /* Backward substitution along the same column.
         We keep the 'next' value (v[j+1][i]) in a register (v_next)
         instead of reloading it from memory. */
      v_[nPB - 1][i] = boundary_value;
      DATA_TYPE v_next = boundary_value; /* v_[nPB - 1][i] */

      for (int j = nPB - 2; j >= 1; --j)
      {
        const DATA_TYPE v_curr = p_row[j] * v_next + q_row[j];
        v_[j][i] = v_curr;
        v_next   = v_curr;
      }
    }

    /* --------------------------------------------------------------
       Row Sweep
       --------------------------------------------------------------
       Symmetric to the column sweep, but now solving along rows of u_,
       using v_ as the input field. Again, iterations in i are
       independent and are parallelized.
    */
#pragma omp parallel for schedule(static)
    for (int i = 1; i < nPB - 1; ++i)
    {
      DATA_TYPE * __restrict p_row = p_[i];
      DATA_TYPE * __restrict q_row = q_[i];

      /* Boundary conditions on this row (i is fixed). */
      u_[i][0] = boundary_value;
      p_row[0] = zero;
      q_row[0] = boundary_value; /* equal to u_[i][0] */

      /* Forward sweep along the row (increasing j). */
      for (int j = 1; j < nPB - 1; ++j)
      {
        const DATA_TYPE denom     = d * p_row[j - 1] + e;
        const DATA_TYPE inv_denom = one / denom;

        p_row[j] = -f * inv_denom;

        const DATA_TYPE vim1_j = v_[i - 1][j];
        const DATA_TYPE vi_j   = v_[i][j];
        const DATA_TYPE vip1_j = v_[i + 1][j];

        const DATA_TYPE rhs =
          (-a * vim1_j) + (center_a * vi_j) - (c * vip1_j) - (d * q_row[j - 1]);

        q_row[j] = rhs * inv_denom;
      }

      /* Backward substitution along the row. */
      u_[i][nPB - 1] = boundary_value;
      DATA_TYPE u_next = boundary_value; /* u_[i][nPB - 1] */

      for (int j = nPB - 2; j >= 1; --j)
      {
        const DATA_TYPE u_curr = p_row[j] * u_next + q_row[j];
        u_[i][j] = u_curr;
        u_next   = u_curr;
      }
    }
  }
#pragma endscop
}


